use super::error::{ConfigError, ConfigResult};
use super::models::*;
use super::validation::ConfigValidator;
use chrono::{DateTime, Utc};
use json_patch::{Patch, PatchOperation};
use lazy_static::lazy_static;
use serde::Serialize;
use serde_json;
use std::fs;
use std::path::{Path, PathBuf};

/// Update partial configuration (for API updates)
pub fn update_partial(&mut self, updates: serde_json::Value) -> ConfigResult<()> {
    // Parse the JSON Patch operations
    let patch: Patch = serde_json::from_value(updates)
        .map_err(|e| ConfigError::InvalidJson { source: e })?;

    // Convert self to JSON Value for patch operations
    let mut config_value = serde_json::to_value(&*self)
        .map_err(|e| ConfigError::InvalidJson { source: e })?;

    // Apply the patch operations
    json_patch::patch(&mut config_value, &patch)
        .map_err(|e| ConfigError::ValidationError { 
            field: "patch".to_string(), 
            message: format!("Failed to apply JSON patch: {}", e) 
        })?;

    // Convert back to AppConfig and validate
    let updated_config: AppConfig = serde_json::from_value(config_value)
        .map_err(|e| ConfigError::InvalidJson { source: e })?;

    // Validate the updated configuration
    updated_config.validate()?;

    // Apply the updates to self
    *self = updated_config;

    // Preserve the loaded_from path if it was set
    if self.loaded_from.is_none() {
        // If no loaded_from was preserved from the deserialization, use the original
        // This can happen because loaded_from is marked with #[serde(skip)]
        self.loaded_from = self.loaded_from.clone();
    }

    Ok(())
}

