/// Update partial configuration (for API updates)
pub fn update_partial(&mut self, updates: serde_json::Value) -> ConfigResult<()> {
    // Parse the JSON Patch operations
    let patch: Patch = serde_json::from_value(updates)
        .map_err(|e| ConfigError::InvalidJson { source: e })?;

    // Convert self to JSON Value for patch operations
    let mut config_value = serde_json::to_value(&*self)
        .map_err(|e| ConfigError::InvalidJson { source: e })?;

    // Apply the patch operations
    json_patch::patch(&mut config_value, &patch)
        .map_err(|e| ConfigError::ValidationFailed { 
            field: "patch".to_string(), 
            message: format!("Failed to apply JSON patch: {e}") 
        })?;

    // Convert back to AppConfig and validate
    let mut updated_config: AppConfig = serde_json::from_value(config_value)
        .map_err(|e| ConfigError::InvalidJson { source: e })?;

    // Validate the updated configuration
    updated_config.validate()?;

    // Preserve the loaded_from path since it's marked with #[serde(skip)]
    let original_loaded_from = self.loaded_from.clone();

    // Apply the updates to self
    *self = updated_config;
    self.loaded_from = original_loaded_from;

    Ok(())
}

